import { test, expect } from '@playwright/test';

test.describe('Table Loading State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display loading state while data is fetching', async ({ page }) => {
    // Intercept the API call to simulate loading
    await page.route('**/api/table/data', (route) => {
      setTimeout(() => {
        route.abort('failed');
      }, 3000);
    });

    // Verify table container is visible
    const tableContainer = page.getByRole('region', { name: /table/i });
    await expect(tableContainer).toBeVisible();

    // Verify loading spinner is visible
    const loadingSpinner = page.getByRole('status', { name: /loading/i });
    await expect(loadingSpinner).toBeVisible();

    // Verify loading message is displayed
    const loadingMessage = page.getByText(/loading data/i);
    await expect(loadingMessage).toBeVisible();

    // Verify table rows are not yet visible
    const tableRows = page.getByRole('row');
    await expect(tableRows).toHaveCount(0);

    // Wait for loading to complete
    await page.waitForTimeout(3500);

    // Verify loading spinner is no longer visible
    await expect(loadingSpinner).not.toBeVisible();

    // Verify loading message is no longer visible
    await expect(loadingMessage).not.toBeVisible();

    // Verify table rows are now visible
    await expect(tableRows).toHaveCount(5);

    // Verify table data is displayed
    const tableData = page.getByText(/sample data/i);
    await expect(tableData).toBeVisible();
  });

  test('should handle loading state with error and display error message', async ({ page }) => {
    // Intercept the API call to simulate error
    await page.route('**/api/table/data', (route) => {
      setTimeout(() => {
        route.abort('failed');
      }, 1000);
    });

    // Verify table container is visible
    const tableContainer = page.getByRole('region', { name: /table/i });
    await expect(tableContainer).toBeVisible();

    // Verify loading spinner is visible
    const loadingSpinner = page.getByRole('status', { name: /loading/i });
    await expect(loadingSpinner).toBeVisible();

    // Wait for loading to complete
    await page.waitForTimeout(1100);

    // Verify loading spinner is no longer visible
    await expect(loadingSpinner).not.toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/failed to load data/i);
    await expect(errorMessage).toBeVisible();

    // Verify table rows are not visible
    const tableRows = page.getByRole('row');
    await expect(tableRows).toHaveCount(0);

    // Verify retry button is visible
    const retryButton = page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();

    // Click retry button
    await retryButton.click();

    // Verify loading spinner reappears
    await expect(loadingSpinner).toBeVisible();

    // Wait for retry to complete
    await page.waitForTimeout(1100);

    // Verify error message is gone
    await expect(errorMessage).not.toBeVisible();

    // Verify table rows are now visible
    await expect(tableRows).toHaveCount(5);
  });
});
